// Preparar texto de seguimiento para enviarlo TÚ manualmente por WhatsApp
const d = $input.first().json;
const texto = `Hola ${d.nombre_cliente}! Han pasado 24h desde que recibiste el pedido ${d.numero_pedido}. Todo llegó bien? Estás contento con tu compra? Gracias!`;
return [{ json: {
  numero_pedido: d.numero_pedido,
  telefono: d.telefono,
  nombre_cliente: d.nombre_cliente,
  texto_para_enviar: texto,
  timestamp: new Date().toISOString()
}}];
